using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool Definitions ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
string SearchWeb(string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search).
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    return query.ToLowerInvariant() switch
    {
        var q when q.Contains("quantum computing") && q.Contains("2026") =>
            """
            1. In 2026, IBM unveiled a 10,000-qubit processor codenamed 'Condor X', achieving quantum advantage in molecular simulation.
            2. Google DeepMind announced a hybrid quantum-classical system that reduces drug discovery timelines by 60%.
            3. Microsoft released Azure Quantum 2.0 with topological qubits reaching error rates below 0.01%.
            4. China's Jiuzhang 4.0 photonic quantum computer solved a boson sampling problem in 200 seconds that would take classical supercomputers 10,000 years.
            5. Startups like PsiQuantum began shipping rack-scale photonic quantum computers to data centers.
            """,
        var q when q.Contains("quantum") && q.Contains("application") =>
            """
            1. Quantum computing is being applied to portfolio optimization in finance, with JPMorgan reporting 40% faster risk calculations.
            2. Pharmaceutical companies use quantum simulations to model protein folding, accelerating vaccine development.
            3. Logistics companies leverage quantum annealing for route optimization, saving an estimated 15% in fuel costs.
            """,
        var q when q.Contains("quantum") =>
            """
            1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
            2. Major players include IBM, Google, Microsoft, and several startups.
            3. Key challenges remain: decoherence, error correction, and scaling qubit counts.
            """,
        _ =>
            $"1. General information about '{query}' is available from multiple sources.\n" +
            $"2. Recent developments in '{query}' show significant progress.\n" +
            $"3. Experts predict continued growth in this area."
    };
}

[Description("Save a note for later reference. Use this to record key findings during research.")]
string TakeNote(string note)
{
    Console.WriteLine($"  [Tool] Saving note: \"{note[..Math.Min(note.Length, 80)]}...\"");
    notes.Add(note);
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved notes to review findings before writing a summary.")]
string GetNotes()
{
    Console.WriteLine("  [Tool] Retrieving all notes...");
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n\n", notes.Select((n, i) => $"Note {i + 1}: {n}"));
}

// --- Agent Setup ---

var topic = args.Length > 0 ? string.Join(' ', args) : "quantum computing breakthroughs in 2026";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Topic: {topic}");
Console.WriteLine(new string('-', 60));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(SearchWeb),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System,
        """
        You are a research agent. Your goal is to research the given topic thoroughly and produce a well-organized summary.

        Follow this process:
        1. Search the web for information about the topic (perform 2-3 searches with different angles).
        2. Take notes on the most important findings from each search.
        3. Retrieve your notes and synthesize them into a clear, structured summary.

        Always use your tools — do not make up information. When you have enough information, 
        retrieve your notes and write a final summary with key points and conclusions.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

// --- Agent Loop ---

Console.WriteLine("\nAgent is researching...\n");

var response = await client.GetResponseAsync(messages, tools);

Console.WriteLine(new string('-', 60));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('-', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('-', 60));
Console.WriteLine($"\nNotes collected: {notes.Count}");

